// Tests for src/sidebar-groups.mjs: the autogenerated `cli` directory group under
// "Using Brahma" is shown as a collapsed "CLI reference" group, and the other
// directory groups (concepts, safety, guides, decisions, modules, brahmacore) get
// their labels without being forced closed.
//
// Run: npm test (node --test).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { relabelGroups, GROUP_LABELS } from '../src/sidebar-groups.mjs';

const link = (href, label, isCurrent = false) => ({ type: 'link', label, href, isCurrent, badge: undefined, attrs: {} });
const group = (label, entries) => ({ type: 'group', label, entries, collapsed: false, badge: undefined });

function sidebar() {
  return [
    group('Using Brahma', [
      link('/docs/', 'Using Brahma'),
      group('concepts', [link('/docs/concepts/companies/', 'Companies')]),
      group('cli', [
        link('/docs/cli/', 'Overview'),
        group('company', [link('/docs/cli/company/', 'Overview'), link('/docs/cli/company/create/', 'create', true)]),
        link('/docs/cli/log/', 'log'),
      ]),
    ]),
    group('Inside Brahma', [group('cli', [link('/internals/cli/', 'Not the reference')])]),
  ];
}

/** [label, collapsed] of each subgroup of `g`, in order. */
const groups = (g) => g.entries.filter((e) => e.type === 'group').map((e) => [e.label, e.collapsed]);

test('the docs/cli group is relabelled "CLI reference" and collapsed, nested groups too', () => {
  const s = sidebar();
  relabelGroups(s, GROUP_LABELS);
  const cli = s[0].entries[2];
  assert.equal(cli.label, 'CLI reference');
  assert.equal(cli.collapsed, true);
  assert.equal(cli.entries[1].label, 'company', 'nested group labels are kept');
  assert.equal(cli.entries[1].collapsed, true);
  assert.equal(cli.entries[1].entries[1].isCurrent, true, 'current entry untouched');
});

test('groups outside the mapping are left alone, including a "cli" group outside /docs/cli/', () => {
  const s = sidebar();
  relabelGroups(s, GROUP_LABELS);
  assert.equal(s[0].label, 'Using Brahma');
  assert.equal(s[0].collapsed, false);
  assert.equal(s[1].entries[0].label, 'cli');
  assert.equal(s[1].entries[0].collapsed, false);
});

test('a sidebar without the generated reference is unchanged', () => {
  const s = [group('Using Brahma', [link('/docs/', 'Using Brahma')])];
  const before = structuredClone(s);
  relabelGroups(s, GROUP_LABELS);
  assert.deepEqual(s, before);
});

test('directory groups get their labels and keep their collapsed state; brahmacore inside modules too', () => {
  const s = [
    group('Using Brahma', [
      link('/docs/', 'Using Brahma'),
      group('concepts', [link('/docs/concepts/', 'Concepts'), link('/docs/concepts/companies/', 'Companies')]),
      group('safety', [link('/docs/safety/profiles/', 'Profiles')]),
      group('guides', [link('/docs/guides/first-company/', 'First company')]),
      group('cli', [link('/docs/cli/', 'Overview')]),
    ]),
    group('Inside Brahma', [
      link('/internals/', 'Inside Brahma'),
      group('decisions', [link('/internals/decisions/', 'Decisions')]),
      group('modules', [
        link('/internals/modules/', 'Modules'),
        link('/internals/modules/brahmaapp/', 'BrahmaApp', true),
        group('brahmacore', [link('/internals/modules/brahmacore/', 'BrahmaCore'), link('/internals/modules/brahmacore/work/', 'Work')]),
      ]),
    ]),
  ];
  relabelGroups(s, GROUP_LABELS);
  assert.deepEqual(groups(s[0]), [['Concepts', false], ['Safety', false], ['Guides', false], ['CLI reference', true]]);
  assert.deepEqual(groups(s[1]), [['Decisions', false], ['Modules', false]]);
  const modules = s[1].entries[2];
  assert.deepEqual(groups(modules), [['BrahmaCore', false]]);
  assert.equal(modules.entries[1].isCurrent, true, 'current entry untouched');
  assert.equal(modules.entries[2].entries[1].label, 'Work', 'page links untouched');
});

test('a directory name under the wrong URL prefix is not relabelled', () => {
  const s = [
    group('Using Brahma', [group('decisions', [link('/docs/decisions/x/', 'x')])]),
    group('Inside Brahma', [group('concepts', [link('/internals/concepts/y/', 'y')])]),
  ];
  const before = structuredClone(s);
  relabelGroups(s, GROUP_LABELS);
  assert.deepEqual(s, before);
});

test('every mapping entry names a directory, a label and a collapse flag', () => {
  for (const [prefix, entry] of Object.entries(GROUP_LABELS)) {
    assert.match(prefix, /^\/.*\/$/, `${prefix} is a URL prefix with both slashes`);
    assert.equal(typeof entry.dir, 'string');
    assert.equal(typeof entry.label, 'string');
    assert.equal(typeof entry.collapse, 'boolean');
  }
  assert.equal(GROUP_LABELS['/docs/cli/'].collapse, true, 'the CLI reference keeps collapsing');
});
